import type { DepositFlowStep } from './types';

interface StepIndicatorProps {
  steps: { key: DepositFlowStep; label: string }[];
  currentStepIndex: number;
  currentStep: DepositFlowStep;
}

export function StepIndicator({ steps, currentStepIndex, currentStep }: StepIndicatorProps) {
  return (
    <div className="cedros-deposit-flow-steps">
      {steps.map((s, idx) => {
        const isActive = currentStepIndex >= idx;
        const isCurrent = s.key === currentStep;
        return (
          <div
            key={s.key}
            className={`cedros-deposit-flow-step-item ${isActive ? 'step-active' : ''}`}
          >
            <div
              className={`cedros-deposit-flow-step-circle ${isActive ? 'active' : ''} ${isCurrent ? 'current' : ''}`}
            >
              {idx + 1}
            </div>
            <span className={`cedros-deposit-flow-step-label ${isActive ? 'active' : ''}`}>
              {s.label}
            </span>
          </div>
        );
      })}
    </div>
  );
}
