import { useCallback, useState } from 'react';

export interface KycBannerProps {
  /** Current KYC status */
  status: string;
  /** Function that starts verification and returns redirect URL */
  startVerification: () => Promise<string>;
  /** Optional CSS class name */
  className?: string;
}

/**
 * Banner prompting users to complete KYC identity verification.
 *
 * Shown when KYC enforcement is active and the user is not yet verified.
 * Clicking the button starts a Stripe Identity session and redirects the user.
 */
export function KycBanner({
  status,
  startVerification,
  className,
}: KycBannerProps) {
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleVerify = useCallback(async () => {
    setIsLoading(true);
    setError(null);
    try {
      const redirectUrl = await startVerification();
      if (redirectUrl) {
        window.location.href = redirectUrl;
      }
    } catch (err) {
      setError(
        err instanceof Error ? err.message : 'Failed to start verification'
      );
    } finally {
      setIsLoading(false);
    }
  }, [startVerification]);

  // Don't show banner if user is verified
  if (status === 'verified') {
    return null;
  }

  let message: string;
  switch (status) {
    case 'pending':
      message = 'Your identity verification is being processed.';
      break;
    case 'failed':
      message = 'Identity verification failed. Please try again.';
      break;
    case 'expired':
      message = 'Your identity verification has expired. Please verify again.';
      break;
    case 'canceled':
      message = 'Verification was canceled. Please try again.';
      break;
    default:
      message = 'Identity verification is required to continue.';
      break;
  }

  const showButton = status !== 'pending';

  return (
    <div
      className={`cedros-kyc-banner ${className ?? ''}`}
      role="alert"
    >
      <div className="cedros-kyc-banner-content">
        <span className="cedros-kyc-banner-message">{message}</span>
        {showButton && (
          <button
            type="button"
            className="cedros-kyc-banner-button"
            onClick={handleVerify}
            disabled={isLoading}
          >
            {isLoading ? 'Starting...' : 'Verify Identity'}
          </button>
        )}
      </div>
      {error && (
        <div className="cedros-kyc-banner-error">{error}</div>
      )}
    </div>
  );
}
