/**
 * Polling hook for deposit status detection.
 * Handles both real polling and demo auto-confirm.
 */
import { useEffect } from 'react';
import type { DepositConfigResponse } from '../../../types/deposit';
import type { Token } from '../tokens';
import type { DepositFlowResult, DepositFlowStep, DepositMethod } from './types';

interface UseDepositPollingOptions {
  step: DepositFlowStep;
  sessionId: string | null;
  demoMode: boolean;
  demoAutoConfirmMs?: number;
  depositMethod: DepositMethod;
  depositAddress: string | null;
  receiveAmountUsd: number | null;
  selectedToken: Token;
  currencyMode: string;
  config: DepositConfigResponse;
  solanaPubkey: string | null;
  pollInterval: number;
  getStatus: (sessionId: string) => Promise<{
    status: string;
    amountLamports?: number | null;
    txSignature?: string | null;
  }>;
  onSuccess?: (result: DepositFlowResult) => void;
  setResult: (result: DepositFlowResult) => void;
  setStep: (step: DepositFlowStep) => void;
  setFlowError: (error: string) => void;
}

export function useDepositPolling({
  step,
  sessionId,
  demoMode,
  demoAutoConfirmMs,
  depositMethod,
  depositAddress,
  receiveAmountUsd,
  selectedToken,
  currencyMode,
  config,
  solanaPubkey,
  pollInterval,
  getStatus,
  onSuccess,
  setResult,
  setStep,
  setFlowError,
}: UseDepositPollingOptions) {
  // Real polling: auto-detect deposit on confirm / show-address / waiting steps
  useEffect(() => {
    const isListeningStep = step === 'confirm' || step === 'show-address' || step === 'waiting';
    if (!isListeningStep || !sessionId || demoMode) return;

    let cancelled = false;
    let pollCount = 0;
    let consecutiveErrors = 0;
    const maxPolls = 360; // 30 minutes at 5s interval
    const maxConsecutiveErrors = 5; // M-07

    const poll = async () => {
      if (cancelled || pollCount >= maxPolls) return;
      pollCount++;

      try {
        const status = await getStatus(sessionId);
        consecutiveErrors = 0;

        if (status.status === 'completed' || status.status === 'detected') {
          const detectedAmount = status.amountLamports
            ? status.amountLamports / Math.pow(10, selectedToken.decimals)
            : 0;
          const smallestUnit = status.amountLamports || 0;

          const flowResult: DepositFlowResult = {
            token: currencyMode === 'sol' ? null : selectedToken,
            amount: detectedAmount,
            amountSmallestUnit: smallestUnit,
            txSignature: status.txSignature || '',
            sessionId,
            response: status as never,
            method: 'receive',
            depositAddress: solanaPubkey ?? undefined,
          };

          setResult(flowResult);
          setStep('success');
          onSuccess?.(flowResult);
          return;
        }
      } catch {
        consecutiveErrors++;
        if (consecutiveErrors >= maxConsecutiveErrors) {
          setFlowError(
            'Unable to check deposit status. Please check your connection and try again.'
          );
          return;
        }
      }

      if (!cancelled) {
        setTimeout(poll, pollInterval);
      }
    };

    poll();
    return () => {
      cancelled = true;
    };
  }, [
    step,
    sessionId,
    demoMode,
    getStatus,
    selectedToken,
    currencyMode,
    solanaPubkey,
    onSuccess,
    pollInterval,
    setResult,
    setStep,
    setFlowError,
  ]);

  // Demo auto-confirm for receive mode
  useEffect(() => {
    if (!demoMode || !demoAutoConfirmMs || step !== 'waiting' || depositMethod !== 'receive')
      return;
    if (!depositAddress) return;

    const timeout = window.setTimeout(() => {
      const amountUsd = receiveAmountUsd ?? config.privateMinUsd;
      const tokenAmount =
        selectedToken.symbol === 'SOL' && config.solPriceUsd > 0
          ? amountUsd / config.solPriceUsd
          : amountUsd;
      const smallestUnit = Math.round(tokenAmount * Math.pow(10, selectedToken.decimals));
      const flowResult: DepositFlowResult = {
        token: currencyMode === 'sol' ? null : selectedToken,
        amount: tokenAmount,
        amountSmallestUnit: smallestUnit,
        txSignature: `demo-tx-${Date.now()}`,
        sessionId: sessionId || `demo-session-${Date.now()}`,
        response: {
          sessionId: sessionId || `demo-session-${Date.now()}`,
          txSignature: `demo-tx-${Date.now()}`,
          amountLamports: smallestUnit,
          message: 'Demo deposit detected',
          withdrawalAvailableAt: new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString(),
        },
        method: 'receive',
        depositAddress: depositAddress ?? undefined,
      };
      setResult(flowResult);
      setStep('success');
      onSuccess?.(flowResult);
    }, demoAutoConfirmMs);

    return () => window.clearTimeout(timeout);
  }, [
    demoMode,
    demoAutoConfirmMs,
    step,
    depositMethod,
    depositAddress,
    receiveAmountUsd,
    config,
    selectedToken,
    currencyMode,
    sessionId,
    onSuccess,
    setResult,
    setStep,
  ]);
}
