/**
 * AccountSettings — unified account page with Profile, Security, and Linked Accounts tabs.
 *
 * Composes ProfileTab, TotpSettings, SessionList, and LinkedAccounts into a tabbed layout.
 */

import { useState } from 'react';
import { ProfileTab } from './ProfileTab';
import type { ProfileTabProps } from './ProfileTab';
import { LinkedAccounts } from './LinkedAccounts';
import type { LinkedAccountsProps } from './LinkedAccounts';
import { DeleteAccountSection } from './DeleteAccountSection';
import { TotpSettings } from '../totp';
import { SessionList } from '../sessions/SessionList';
import { useSessions } from '../../hooks/useSessions';

type AccountTab = 'profile' | 'security' | 'linked';

const TAB_LABELS: Record<AccountTab, string> = {
  profile: 'Profile',
  security: 'Security',
  linked: 'Linked Accounts',
};

const TABS: AccountTab[] = ['profile', 'security', 'linked'];

export interface AccountSettingsProps extends ProfileTabProps, LinkedAccountsProps {
  /** Which tab to show initially */
  defaultTab?: AccountTab;
  /** Called when user requests to close the settings page */
  onClose?: () => void;
  /** Called when 2FA status changes */
  onTotpChange?: (enabled: boolean) => void;
  /** Called after the current account is deleted */
  onAccountDeleted?: () => void;
}

export function AccountSettings({
  defaultTab = 'profile',
  onClose,
  onPasswordChange,
  onTotpChange,
  onAccountDeleted,
  onLinkGoogle,
  onLinkApple,
  onAddPasskey,
  onLinkSolana,
  className = '',
}: AccountSettingsProps) {
  const [activeTab, setActiveTab] = useState<AccountTab>(defaultTab);
  const { sessions, isLoading: sessionsLoading, error: sessionsError, revokeAllSessions } = useSessions();

  return (
    <div className={`cedros-account-settings ${className}`}>
      {/* Tab bar */}
      <div className="cedros-account-tabs--line" role="tablist">
        {TABS.map((tab) => (
          <button
            key={tab}
            type="button"
            role="tab"
            aria-selected={activeTab === tab}
            className={`cedros-account-tab ${activeTab === tab ? 'cedros-account-tab-active' : ''}`}
            onClick={() => setActiveTab(tab)}
          >
            {TAB_LABELS[tab]}
          </button>
        ))}
      </div>

      {/* Tab content */}
      <div className="cedros-account-tab-content" role="tabpanel">
        {activeTab === 'profile' && (
          <ProfileTab onPasswordChange={onPasswordChange} />
        )}

        {activeTab === 'security' && (
          <div className="cedros-account-security">
            <TotpSettings onStatusChange={onTotpChange} />
            <SessionList
              sessions={sessions}
              isLoading={sessionsLoading}
              error={sessionsError ?? undefined}
              onRevokeAll={async () => { await revokeAllSessions(); }}
            />
            <DeleteAccountSection onDeleted={onAccountDeleted} />
          </div>
        )}

        {activeTab === 'linked' && (
          <LinkedAccounts
            onLinkGoogle={onLinkGoogle}
            onLinkApple={onLinkApple}
            onAddPasskey={onAddPasskey}
            onLinkSolana={onLinkSolana}
          />
        )}
      </div>

      {onClose && (
        <div className="cedros-account-footer">
          <button
            type="button"
            className="cedros-button cedros-button-outline cedros-button-md"
            onClick={onClose}
          >
            Close
          </button>
        </div>
      )}
    </div>
  );
}
