/**
 * Pure helper utilities for the profile settings UI.
 */

interface UserLike {
  name?: string | null;
  email?: string | null;
}

/**
 * Returns up to two initials for avatar fallback display.
 *
 * @param user - Object with optional name and email fields.
 * @returns 1–2 uppercase characters, or '?' when neither field is set.
 */
export function getInitials(user: UserLike | null | undefined): string {
  if (user?.name) {
    return user.name
      .split(' ')
      .map((n) => n[0])
      .join('')
      .toUpperCase()
      .slice(0, 2);
  }
  if (user?.email) {
    return user.email[0].toUpperCase();
  }
  return '?';
}
