import { useState, useCallback, useMemo } from 'react';
import { useCedrosLogin } from '../context/useCedrosLogin';
import { ApiClient } from '../utils/apiClient';

interface ReferralInfo {
  referralCode: string;
  referralCount: number;
  directPayoutEnabled: boolean;
}

interface RegenerateResponse {
  referralCode: string;
}

/**
 * Return type for the useReferral hook
 */
export interface UseReferralReturn {
  /** Fetch the current user's referral code and count */
  getReferral: () => Promise<ReferralInfo>;
  /** Regenerate the current user's referral code */
  regenerateCode: () => Promise<string>;
  /** Whether a request is in progress */
  isLoading: boolean;
  /** Error from the last operation */
  error: Error | null;
}

/**
 * Hook for referral code management.
 *
 * @example
 * ```tsx
 * const { getReferral, regenerateCode, isLoading } = useReferral();
 *
 * const info = await getReferral();
 * console.log(info.referralCode, info.referralCount);
 *
 * const newCode = await regenerateCode();
 * ```
 */
export function useReferral(): UseReferralReturn {
  const { config, _internal } = useCedrosLogin();
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<Error | null>(null);

  const apiClient = useMemo(
    () =>
      new ApiClient({
        baseUrl: config.serverUrl,
        timeoutMs: config.requestTimeout,
        getAccessToken: _internal?.getAccessToken,
      }),
    [config.serverUrl, config.requestTimeout, _internal]
  );

  const getReferral = useCallback(async (): Promise<ReferralInfo> => {
    setIsLoading(true);
    setError(null);
    try {
      const resp = await apiClient.get<ReferralInfo>('/referral', {
        credentials: 'include',
      });
      return resp;
    } catch (err) {
      const e = err instanceof Error ? err : new Error(String(err));
      setError(e);
      throw e;
    } finally {
      setIsLoading(false);
    }
  }, [apiClient]);

  const regenerateCode = useCallback(async (): Promise<string> => {
    setIsLoading(true);
    setError(null);
    try {
      const resp = await apiClient.post<RegenerateResponse>('/referral/regenerate', undefined, {
        credentials: 'include',
      });
      return resp.referralCode;
    } catch (err) {
      const e = err instanceof Error ? err : new Error(String(err));
      setError(e);
      throw e;
    } finally {
      setIsLoading(false);
    }
  }, [apiClient]);

  return { getReferral, regenerateCode, isLoading, error };
}
