export interface AccreditationBannerProps {
  /** Current accreditation status */
  status: string;
  /** Called when the user clicks the verification action button */
  onStartVerification?: () => void;
  /** Additional CSS class */
  className?: string;
}

/**
 * Banner prompting users to complete accredited investor verification.
 *
 * Returns null when status is "approved". All other statuses render a banner
 * with an optional action button that calls `onStartVerification`.
 *
 * @example
 * ```tsx
 * const [showWizard, setShowWizard] = useState(false);
 * const { status } = useAccreditation();
 * <AccreditationBanner status={status ?? 'none'} onStartVerification={() => setShowWizard(true)} />
 * ```
 */
export function AccreditationBanner({
  status,
  onStartVerification,
  className,
}: AccreditationBannerProps) {
  if (status === 'approved') {
    return null;
  }

  let message: string;
  let showButton = true;

  switch (status) {
    case 'pending':
      message = 'Your accreditation is under review.';
      showButton = false;
      break;
    case 'rejected':
      message = 'Accreditation was not approved. You can resubmit.';
      break;
    case 'expired':
      message = 'Your accreditation has expired. Please verify again.';
      break;
    default:
      message = 'Accredited investor verification is required.';
      break;
  }

  return (
    <div
      className={`cedros-accreditation-banner ${className ?? ''}`}
      role="alert"
    >
      <div className="cedros-accreditation-banner__content">
        <span className="cedros-accreditation-banner__message">{message}</span>
        {showButton && onStartVerification && (
          <button
            type="button"
            className="cedros-accreditation-banner__button"
            onClick={onStartVerification}
          >
            {status === 'rejected' || status === 'expired'
              ? 'Resubmit Verification'
              : 'Start Verification'}
          </button>
        )}
      </div>
    </div>
  );
}
