import type { DepositConfigResponse } from '../../../types/deposit';
import { LAMPORTS_PER_SOL } from './tokenUtils';

export interface FeeLineItem {
  label: string;
  solAmount: number;
  percent: number;
  usdAmount: number;
}

/** Check if any user-facing fee is enabled */
export function hasUserFee(config: DepositConfigResponse): boolean {
  return (
    config.companyFeePercent > 0 ||
    config.feePolicy === 'user_pays_all' ||
    config.feePolicy === 'user_pays_swap' ||
    config.feePolicy === 'user_pays_privacy'
  );
}

/** Calculate effective fee percentage based on config and deposit type */
export function getEffectiveFeePercent(
  config: DepositConfigResponse,
  isPrivate: boolean,
  isMicro: boolean
): number {
  const { feePolicy, privacyFeePercent, swapFeePercent, companyFeePercent } = config;
  let userFee = companyFeePercent;
  if (isMicro) return userFee;
  if (feePolicy === 'user_pays_all') {
    userFee += swapFeePercent;
    if (isPrivate) {
      userFee += privacyFeePercent;
    }
  } else if (feePolicy === 'user_pays_privacy' && isPrivate) {
    userFee += privacyFeePercent;
  } else if (feePolicy === 'user_pays_swap') {
    userFee += swapFeePercent;
  }
  return userFee;
}

export function calculateFeeLines(config: DepositConfigResponse, amountUsd: number): FeeLineItem[] {
  const isMicro = amountUsd < config.publicMinUsd;
  const isPrivate = amountUsd >= config.privateMinUsd;
  const lines: FeeLineItem[] = [];

  const privacyActive =
    !isMicro &&
    isPrivate &&
    (config.feePolicy === 'user_pays_all' || config.feePolicy === 'user_pays_privacy') &&
    (config.privacyFeeFixedLamports > 0 || config.privacyFeePercent > 0);
  const swapActive =
    !isMicro &&
    (config.feePolicy === 'user_pays_all' || config.feePolicy === 'user_pays_swap') &&
    (config.swapFeeFixedLamports > 0 || config.swapFeePercent > 0);
  const companyActive = config.companyFeeFixedLamports > 0 || config.companyFeePercent > 0;

  if (privacyActive) {
    const solAmount = config.privacyFeeFixedLamports / LAMPORTS_PER_SOL;
    const percent = config.privacyFeePercent;
    const fixedUsd = solAmount * config.solPriceUsd;
    const percentUsd = amountUsd * (percent / 100);
    lines.push({ label: 'Privacy', solAmount, percent, usdAmount: fixedUsd + percentUsd });
  }
  if (swapActive) {
    const solAmount = config.swapFeeFixedLamports / LAMPORTS_PER_SOL;
    const percent = config.swapFeePercent;
    const fixedUsd = solAmount * config.solPriceUsd;
    const percentUsd = amountUsd * (percent / 100);
    lines.push({ label: 'Swap', solAmount, percent, usdAmount: fixedUsd + percentUsd });
  }
  if (companyActive) {
    const solAmount = config.companyFeeFixedLamports / LAMPORTS_PER_SOL;
    const percent = config.companyFeePercent;
    const fixedUsd = solAmount * config.solPriceUsd;
    const percentUsd = amountUsd * (percent / 100);
    lines.push({ label: 'Service', solAmount, percent, usdAmount: fixedUsd + percentUsd });
  }

  return lines;
}

export function formatFeeTooltip(
  config: DepositConfigResponse,
  amountUsd: number,
  totalFeeUsd: number
): string {
  const feeLines = calculateFeeLines(config, amountUsd);
  // H-08: Don't floor zero fees to $0.01 (e.g. company_pays_all)
  const feeTotalDisplay = totalFeeUsd === 0 ? 0 : totalFeeUsd < 0.01 ? 0.01 : totalFeeUsd;

  if (feeLines.length === 0) {
    return totalFeeUsd === 0 ? 'No fees' : `Total: $${feeTotalDisplay.toFixed(2)}`;
  }

  // Calculate totals
  const totalSol = feeLines.reduce((sum, line) => sum + line.solAmount, 0);
  const totalPercent = feeLines.reduce((sum, line) => sum + line.percent, 0);

  // Format as a table with column dividers
  const COL = { fee: 7, sol: 8, rate: 7, usd: 8 };

  const formatLine = (item: FeeLineItem): string => {
    const label = item.label.padEnd(COL.fee);
    const sol = item.solAmount.toFixed(4).padStart(6).padEnd(COL.sol);
    const pct = (item.percent.toFixed(2) + '%').padStart(5).padEnd(COL.rate);
    // H-08: Don't floor zero fees to $0.01
    const usdVal = item.usdAmount === 0 ? 0 : Math.max(item.usdAmount, 0.01);
    const usd = ('$' + usdVal.toFixed(2)).padEnd(COL.usd);
    return `${label} │ ${sol} │ ${pct} │ ${usd}`;
  };

  const header = `${'Fee'.padEnd(COL.fee)} │ ${'SOL'.padEnd(COL.sol)} │ ${'+ Rate'.padEnd(COL.rate)} │ ${'= Total'.padEnd(COL.usd)}`;
  const divider = `${'─'.repeat(COL.fee)}─┼─${'─'.repeat(COL.sol)}─┼─${'─'.repeat(COL.rate)}─┼─${'─'.repeat(COL.usd)}`;

  const totalUsdStr = ('$' + feeTotalDisplay.toFixed(2)).padEnd(COL.usd);
  const totalLine = `${'TOTAL'.padEnd(COL.fee)} │ ${totalSol.toFixed(4).padStart(6).padEnd(COL.sol)} │ ${(totalPercent.toFixed(2) + '%').padStart(5).padEnd(COL.rate)} │ ${totalUsdStr}`;

  const lines = [header, divider, ...feeLines.map(formatLine), divider, totalLine];
  return lines.join('\n');
}

export function formatExplainerFeeSummary(config: DepositConfigResponse): string {
  const hasPrivacyFee = config.privacyFeeFixedLamports > 0 || config.privacyFeePercent > 0;
  const hasSwapFee = config.swapFeeFixedLamports > 0 || config.swapFeePercent > 0;
  const hasCompanyFee = config.companyFeeFixedLamports > 0 || config.companyFeePercent > 0;

  if (!hasPrivacyFee && !hasSwapFee && !hasCompanyFee) {
    return 'No processing fees apply to deposits.';
  }

  return "A small fee may apply. We'll show exact totals before you confirm.";
}

export function getTotalFeeUsd(config: DepositConfigResponse, amountUsd: number): number {
  if (amountUsd <= 0) return 0;
  const isMicro = amountUsd < config.publicMinUsd;
  const isPrivate = amountUsd >= config.privateMinUsd;
  const feePercent = getEffectiveFeePercent(config, isPrivate, isMicro);
  let userFixedLamports = config.companyFeeFixedLamports;
  if (!isMicro) {
    if (
      isPrivate &&
      (config.feePolicy === 'user_pays_all' || config.feePolicy === 'user_pays_privacy')
    ) {
      userFixedLamports += config.privacyFeeFixedLamports;
    }
    if (config.feePolicy === 'user_pays_all' || config.feePolicy === 'user_pays_swap') {
      userFixedLamports += config.swapFeeFixedLamports;
    }
  }
  const fixedFeeUsd = (userFixedLamports / LAMPORTS_PER_SOL) * config.solPriceUsd;
  const percentFeeUsd = amountUsd * (feePercent / 100);
  return fixedFeeUsd + percentFeeUsd;
}
