import { useState, useCallback, useMemo } from 'react';
import { useCedrosLogin } from '../context/useCedrosLogin';
import { ApiClient } from '../utils/apiClient';

interface RewardsInfo {
  totalEarned: number;
  pendingAmount: number;
  pendingCount: number;
  currency: string;
  rewardType: string;
  payoutWalletAddress: string | null;
  referralCount: number;
}

interface RewardHistoryItem {
  id: string;
  triggerType: string;
  amount: number;
  currency: string;
  status: string;
  txSignature: string | null;
  createdAt: string;
  completedAt: string | null;
}

interface RewardsHistoryResponse {
  items: RewardHistoryItem[];
  total: number;
}

interface SetPayoutWalletRequest {
  walletAddress: string | null;
}

/**
 * Return type for the useRewards hook.
 *
 * Inputs: none (reads config from CedrosLoginProvider context)
 * Outputs: rewards summary, history list, and mutation methods
 * Errors: all methods throw on failure and set `error` state
 * Invariants: `isLoading` is true only while a request is in flight
 */
export interface UseRewardsReturn {
  /** Rewards summary data */
  rewards: RewardsInfo | null;
  /** Reward history items */
  history: RewardHistoryItem[];
  /** Total history count */
  historyTotal: number;
  /** Fetch rewards summary */
  fetchRewards: () => Promise<RewardsInfo>;
  /** Fetch reward history (paginated) */
  fetchHistory: (limit?: number, offset?: number) => Promise<RewardsHistoryResponse>;
  /** Set payout wallet address (null to clear) */
  setPayoutWallet: (walletAddress: string | null) => Promise<void>;
  /** Whether a request is in progress */
  isLoading: boolean;
  /** Error from the last operation */
  error: Error | null;
}

/**
 * Hook for fetching rewards info and history, and managing payout wallet.
 *
 * @example
 * ```tsx
 * const { rewards, history, fetchRewards, fetchHistory, setPayoutWallet, isLoading } = useRewards();
 *
 * useEffect(() => {
 *   fetchRewards();
 *   fetchHistory(10, 0);
 * }, [fetchRewards, fetchHistory]);
 * ```
 */
export function useRewards(): UseRewardsReturn {
  const { config, _internal } = useCedrosLogin();
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<Error | null>(null);
  const [rewards, setRewards] = useState<RewardsInfo | null>(null);
  const [history, setHistory] = useState<RewardHistoryItem[]>([]);
  const [historyTotal, setHistoryTotal] = useState(0);

  const apiClient = useMemo(
    () =>
      new ApiClient({
        baseUrl: config.serverUrl,
        timeoutMs: config.requestTimeout,
        getAccessToken: _internal?.getAccessToken,
      }),
    [config.serverUrl, config.requestTimeout, _internal]
  );

  const fetchRewards = useCallback(async (): Promise<RewardsInfo> => {
    setIsLoading(true);
    setError(null);
    try {
      const resp = await apiClient.get<RewardsInfo>('/referral/rewards', {
        credentials: 'include',
      });
      setRewards(resp);
      return resp;
    } catch (err) {
      const e = err instanceof Error ? err : new Error(String(err));
      setError(e);
      throw e;
    } finally {
      setIsLoading(false);
    }
  }, [apiClient]);

  const fetchHistory = useCallback(
    async (limit = 10, offset = 0): Promise<RewardsHistoryResponse> => {
      setIsLoading(true);
      setError(null);
      try {
        const resp = await apiClient.get<RewardsHistoryResponse>(
          `/referral/rewards/history?limit=${limit}&offset=${offset}`,
          { credentials: 'include' }
        );
        setHistory(resp.items);
        setHistoryTotal(resp.total);
        return resp;
      } catch (err) {
        const e = err instanceof Error ? err : new Error(String(err));
        setError(e);
        throw e;
      } finally {
        setIsLoading(false);
      }
    },
    [apiClient]
  );

  const setPayoutWallet = useCallback(
    async (walletAddress: string | null): Promise<void> => {
      setIsLoading(true);
      setError(null);
      try {
        await apiClient.post<unknown>(
          '/referral/payout-wallet',
          { walletAddress } satisfies SetPayoutWalletRequest,
          { credentials: 'include' }
        );
        setRewards((prev) =>
          prev ? { ...prev, payoutWalletAddress: walletAddress } : prev
        );
      } catch (err) {
        const e = err instanceof Error ? err : new Error(String(err));
        setError(e);
        throw e;
      } finally {
        setIsLoading(false);
      }
    },
    [apiClient]
  );

  return {
    rewards,
    history,
    historyTotal,
    fetchRewards,
    fetchHistory,
    setPayoutWallet,
    isLoading,
    error,
  };
}
