import type { Token } from '../../tokens';

interface WaitingStepProps {
  token: Token;
  depositAddress: string | null;
  copied: boolean;
  feeLine: string;
  onCopy: () => void;
}

export function WaitingStep({ token, depositAddress, copied, feeLine, onCopy }: WaitingStepProps) {
  return (
    <div className="cedros-deposit-flow-step cedros-deposit-flow-step-centered">
      <div className="cedros-deposit-flow-spinner" />
      <h4 className="cedros-deposit-flow-step-title">Waiting for Deposit</h4>
      <p className="cedros-deposit-flow-step-desc">
        Looking for incoming <strong>{token.symbol}</strong> deposits...
      </p>

      <div className="cedros-deposit-flow-waiting-info">
        <p className="cedros-deposit-flow-waiting-text">
          Once your transaction is confirmed on the Solana network, your account will be credited
          automatically. This usually takes 20-30 seconds.
        </p>
        {depositAddress && (
          <div className="cedros-deposit-flow-field">
            <label className="cedros-deposit-flow-label">Deposit address</label>
            <div className="cedros-deposit-flow-address-box">
              <code className="cedros-deposit-flow-address">
                {depositAddress.slice(0, 6)}...{depositAddress.slice(-6)}
              </code>
              <div className="cedros-deposit-flow-address-actions">
                <button
                  type="button"
                  className="cedros-deposit-flow-copy-btn cedros-deposit-flow-copy-icon"
                  onClick={onCopy}
                  title="Copy address"
                >
                  {copied ? '✓' : '⧉'}
                </button>
                <a
                  className="cedros-deposit-flow-copy-btn cedros-deposit-flow-copy-link cedros-deposit-flow-copy-icon"
                  href={`https://orbmarkets.io/account/${depositAddress}`}
                  target="_blank"
                  rel="noopener noreferrer"
                  title="View on Orb Markets"
                >
                  ↗
                </a>
              </div>
            </div>
          </div>
        )}
        <div className="cedros-deposit-flow-info-stack">
          <div className="cedros-deposit-flow-info-item">
            <span className="cedros-deposit-flow-info-dot" />
            <span>Send only on the Solana network.</span>
          </div>
          <div className="cedros-deposit-flow-info-item">
            <span className="cedros-deposit-flow-info-dot" />
            <span>{feeLine}</span>
          </div>
        </div>
      </div>
    </div>
  );
}
