interface SigningStepProps {
  depositAddress: string | null;
}

export function SigningStep({ depositAddress }: SigningStepProps) {
  return (
    <div className="cedros-deposit-flow-step cedros-deposit-flow-step-centered">
      <div className="cedros-deposit-flow-spinner" />
      <h4 className="cedros-deposit-flow-step-title">Signing Transfer</h4>
      <p className="cedros-deposit-flow-step-desc">
        Approve the transfer in your wallet extension...
      </p>
      {depositAddress && (
        <p className="cedros-deposit-flow-signing-dest">
          Sending to:{' '}
          <code>
            {depositAddress.slice(0, 6)}...{depositAddress.slice(-4)}
          </code>
        </p>
      )}
    </div>
  );
}
