import type { DepositConfigResponse } from '../../../../types/deposit';
import { getTokenUsdPrice, SOL_TOKEN } from '../tokenUtils';
import { getTotalFeeUsd } from '../feeUtils';
import type { DepositFlowResult } from '../types';

interface SuccessStepProps {
  result: DepositFlowResult;
  config: DepositConfigResponse;
  onNewDeposit: () => void;
}

export function SuccessStep({ result, config, onNewDeposit }: SuccessStepProps) {
  const token = result.token ?? SOL_TOKEN;
  const price = getTokenUsdPrice(token, config);
  const amountUsd = price ? result.amount * price : result.amount;
  const totalFeeUsd = getTotalFeeUsd(config, amountUsd);
  const creditsUsd = Math.max(amountUsd - totalFeeUsd, 0);
  // H-08: Don't floor zero fees to $0.01
  const totalFeeDisplay = totalFeeUsd === 0 ? 0 : totalFeeUsd < 0.01 ? 0.01 : totalFeeUsd;

  return (
    <div className="cedros-deposit-flow-step cedros-deposit-flow-step-centered">
      <div className="cedros-deposit-flow-success-icon">✓</div>
      <h4 className="cedros-deposit-flow-step-title">Deposit Successful!</h4>
      <p className="cedros-deposit-flow-step-desc">
        Your deposit of {result.amount.toLocaleString()} {token.symbol} has been received.
      </p>

      <div className="cedros-deposit-flow-summary">
        {/* L-10: Only show transaction link when txSignature is present */}
        {result.txSignature && (
          <div className="cedros-deposit-flow-summary-row">
            <span className="cedros-deposit-flow-summary-label">Transaction</span>
            <span className="cedros-deposit-flow-summary-value cedros-deposit-flow-tx">
              <a
                href={`https://orbmarkets.io/tx/${result.txSignature}`}
                target="_blank"
                rel="noopener noreferrer"
              >
                {result.txSignature.slice(0, 8)}...{result.txSignature.slice(-8)}
              </a>
              <a
                className="cedros-deposit-flow-tx-action"
                href={`https://orbmarkets.io/tx/${result.txSignature}`}
                target="_blank"
                rel="noopener noreferrer"
                aria-label="View transaction on Orb Markets"
                title="View transaction"
              >
                ↗
              </a>
            </span>
          </div>
        )}
        <div className="cedros-deposit-flow-summary-row">
          <span className="cedros-deposit-flow-summary-label">Deposit Amount</span>
          <span className="cedros-deposit-flow-summary-value">${amountUsd.toFixed(2)}</span>
        </div>
        <div className="cedros-deposit-flow-summary-row">
          <span className="cedros-deposit-flow-summary-label">Total Fees</span>
          <span className="cedros-deposit-flow-summary-value cedros-deposit-flow-fee">
            -${totalFeeDisplay.toFixed(2)}
          </span>
        </div>
        <div className="cedros-deposit-flow-summary-row">
          <span className="cedros-deposit-flow-summary-label">Credits Added</span>
          <span className="cedros-deposit-flow-summary-value cedros-deposit-flow-credit">
            +${creditsUsd.toFixed(2)}
          </span>
        </div>
        <div className="cedros-deposit-flow-summary-row">
          <span className="cedros-deposit-flow-summary-label">Available</span>
          <span className="cedros-deposit-flow-summary-value">Immediately</span>
        </div>
      </div>

      <div className="cedros-deposit-flow-actions">
        <button
          type="button"
          className="cedros-deposit-flow-button cedros-deposit-flow-button-primary"
          onClick={onNewDeposit}
        >
          Make Another Deposit
        </button>
      </div>
    </div>
  );
}
